sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
   if (isLoading || newValue === '' || g_form.getValue("student"==='')) {
      return;
   }
   g_form.clearMessages();
   var gaAjaxUtilr = new GlideAjax("AjaxUtils");
   gaAjaxUtilr.addParam('sysparm_name','valStudent');
   gaAjaxUtilr.addParam('sysparam_student_sys_id',g_form.getValue('student'));
   gaAjaxUtilr.addParam('sysparam_training',g_form.getValue('training'));
   gaAjaxUtilr.getXML(callback);
   //Type appropriate comment here, and begin script below
}

function callback(response){
	var answer = response.responseXML.documentElement.getAttribute("answer");
	if(answer == 'true'){
		g_form.addErrorMessage("This student is already enrolled in this training");
		g_form.setValue("student",'');
	}
}
